draw:
var g = 9.8;
var h = p.h;
var w = Math.sqrt(p.k / p.mass);
var x0 = p.mass * g / p.k;
var v0 = Math.sqrt(2 * g * h);
var amp = Math.sqrt(x0 * x0 + (v0 * v0) / (w * w));
var dmax = x0 + amp;
var tf = Math.sqrt(2 * h / g);
var tPeak = (Math.PI - Math.atan2(v0, x0 * w)) / w;
var tc = 2 * tPeak;
var cycle = 2 * tf + tc + 0.4;
var tt = t % cycle;

var drop, comp;
if (tt < tf) { drop = 0.5 * g * tt * tt; comp = 0; }
else if (tt < tf + tc) {
  var tau = tt - tf;
  var u = -x0 * Math.cos(w * tau) + (v0 / w) * Math.sin(w * tau);
  comp = x0 + u;
  drop = h + comp;
} else {
  var tr = Math.min(tt - tf - tc, tf);
  drop = h - 0.5 * g * (tf - tr) * (tf - tr);
  if (drop < 0) drop = 0;
  comp = 0;
}

var span = h + dmax + 0.04;
var pxPerM = (H * 0.58) / span;
var cx = W * 0.40;
var groundY = H * 0.88;
var restTop = groundY - (dmax * pxPerM + H * 0.10);
var springTop = restTop + comp * pxPerM;
var blockBottom = comp > 0 ? springTop : restTop - (h - drop) * pxPerM;

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";
ctx.textAlign = "left";

// ground
ctx.fillStyle = C.faint;
ctx.fillRect(cx - W * 0.18, groundY, W * 0.36, 7);

// spring
ctx.strokeStyle = C.accent;
ctx.lineWidth = 2;
ctx.beginPath();
ctx.moveTo(cx, groundY);
var n = 12;
for (var i = 1; i <= n; i++) {
  var yy = groundY + (springTop - groundY) * i / n;
  var dx = (i % 2 === 0 ? -13 : 13) * (i === n ? 0 : 1);
  ctx.lineTo(cx + dx, yy);
}
ctx.lineTo(cx, springTop);
ctx.stroke();

// markers
ctx.strokeStyle = C.rule;
ctx.setLineDash([3, 4]);
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop); ctx.lineTo(cx + W * 0.30, restTop); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop - h * pxPerM); ctx.lineTo(cx + W * 0.30, restTop - h * pxPerM); ctx.stroke();
ctx.beginPath(); ctx.moveTo(cx - W * 0.24, restTop + dmax * pxPerM); ctx.lineTo(cx + W * 0.30, restTop + dmax * pxPerM); ctx.stroke();
ctx.setLineDash([]);
ctx.fillStyle = C.rule;
ctx.fillText("release point", cx + W * 0.12, restTop - h * pxPerM - 4);
ctx.fillText("spring top, relaxed", cx + W * 0.12, restTop - 4);
ctx.fillText("lowest point", cx + W * 0.12, restTop + dmax * pxPerM - 4);

// height arrow
ctx.strokeStyle = C.figure;
ctx.lineWidth = 1.2;
var ax = cx - W * 0.22;
ctx.beginPath(); ctx.moveTo(ax, restTop - h * pxPerM); ctx.lineTo(ax, restTop); ctx.stroke();
ctx.fillStyle = C.figure;
ctx.fillText("h", ax - 12, (2 * restTop - h * pxPerM) / 2);
ctx.beginPath(); ctx.moveTo(ax, restTop); ctx.lineTo(ax, restTop + dmax * pxPerM); ctx.stroke();
ctx.fillText("d", ax - 12, restTop + dmax * pxPerM / 2);

// block
ctx.fillStyle = C.figure;
ctx.beginPath(); ctx.roundRect(cx - 20, blockBottom - 32, 40, 32, 4); ctx.fill();
ctx.fillStyle = C.paper;
ctx.fillText("m", cx - 5, blockBottom - 12);

out.note = "impact speed v = " + v0.toFixed(3) + " m/s,  static sag x0 = " + x0.toFixed(4) + " m,  max compression d = " + dmax.toFixed(4) + " m,  energy stored = " + (0.5 * p.k * dmax * dmax).toFixed(3) + " J";
